/// Ответ на `query rules`.
pub(crate) fn rules_topic(topic: &str) -> Result<String, String> {
    let key = topic.trim().to_lowercase();
    RULES
        .iter()
        .find(|(names, _)| names.iter().any(|n| *n == key))
        .map(|(names, text)| format!("Команда {}: {text}", names[0]))
        .ok_or_else(|| {
            let all: Vec<&str> = RULES.iter().map(|(names, _)| names[0]).collect();
            format!("темы «{}» нет; есть: {}", topic.trim(), all.join(", "))
        })
}

/// Образец команды для сообщения об отказе: первый JSON из её правила.
pub(crate) fn command_sample(cmd: &str) -> Option<String> {
    let key = cmd.trim().to_lowercase();
    let (names, text) = RULES.iter().find(|(names, _)| names.contains(&key.as_str()))?;
    // Ищется JSON именно этой команды (у темы бывает несколько команд).
    let mark = format!("{{\"cmd\":\"{key}\"");
    let start = text.find(&mark).or_else(|| (names[0] == key).then(|| text.find('{')).flatten())?;
    let mut depth = 0usize;
    for (i, ch) in text[start..].char_indices() {
        match ch {
            '{' => depth += 1,
            '}' => {
                depth -= 1;
                if depth == 0 {
                    return Some(text[start..start + i + 1].to_string());
                }
            }
            _ => {}
        }
    }
    None
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn strange_and_custom_layers() {
        let strange = codex_text(None, "pc.nikis");
        assert!(strange.starts_with("Ты — мастер"));
        assert!(strange.contains("КАМПАНИЯ «ДОМ СТРЭНДЖ»"));
        assert!(strange.contains("фон Сталь"));
        assert!(strange.contains("Адриан Варр"));
        assert!(strange.contains("\"character\":\"pc.nikis\""));
        assert!(!strange.contains("{HERO}"));
        let own = codex_text(Some(("Пепел", "Ирэль")), "pc.hero");
        assert!(own.contains("Главный герой — Ирэль"));
        assert!(!own.contains("Никис"), "{own}");
        assert!(!own.contains("Юссач"));
        assert!(!own.contains("Адриан Варр"));
        assert!(own.contains("правилам 2024 года"));
        // Кодекс стал короче прежних 31 тыс. знаков.
        assert!(own.chars().count() < 20_000, "{}", own.chars().count());
    }

    #[test]
    fn every_command_in_codex_has_rules_and_sample() {
        for cmd in [
            "hp",
            "resource",
            "condition",
            "cast",
            "slot",
            "restore",
            "prepare",
            "copy_spell",
            "item",
            "buy",
            "treasury",
            "transfer",
            "new_asset",
            "scene",
            "move",
            "rest",
            "combat",
            "roll",
            "expect_roll",
            "roll_total",
            "note",
            "new_card",
            "edit_card",
            "card",
            "goal",
            "chronicle",
            "xp_note",
            "xp",
            "propose_sheet",
            "recruit",
            "query",
        ] {
            assert!(rules_topic(cmd).is_ok(), "нет правила {cmd}");
            let sample = command_sample(cmd).unwrap_or_else(|| panic!("нет образца {cmd}"));
            let value: serde_json::Value = serde_json::from_str(&sample)
                .unwrap_or_else(|e| panic!("образец {cmd} не JSON: {e}: {sample}"));
            assert_eq!(value["cmd"], cmd, "{sample}");
        }
        assert!(rules_topic("нечто").unwrap_err().contains("recruit"));
    }
}
